contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(string calldata description) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(msg.sender != c.jojoTeam(), "caller must not be jojoTeam");

        uint256 balanceBefore = address(this).balance;
        bool reverted;

        c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted &&
            address(this).balance == balanceBefore
        );
    }

    receive() external payable {}
}

